head.script:
scwin.onpageload = function() {
    try {
        console.log("GitHub 콜백 페이지 로드됨");
        console.log("현재 URL:", window.location.href);

        // URL 쿼리 파라미터에서 인증 결과 확인
        const params = new URLSearchParams(window.location.search);
        const status = params.get('status');
        const username = params.get('username');
        const hasSelectedRepo = params.get('hasSelectedRepo');
        const message = params.get('message');

        console.log("URL 파라미터:", { status, username, hasSelectedRepo, message });

        // 콜백 결과 처리
        const result = {
            status: status || 'success',
            data: {
                message: message || 'GitHub 인증이 완료되었습니다.',
                username: username,
                hasSelectedRepo: hasSelectedRepo === 'true',
                user: username ? { login: username } : null
            }
        };

        console.log("콜백 결과:", result);

        // 부모 창(팝업 opener)으로 결과 전달
        scwin.sendResultToParent(result);

    } catch (e) {
        console.error("콜백 처리 중 오류 발생:", e);

        const errorResult = {
            status: 'error',
            data: {
                message: '콜백 처리 중 오류가 발생했습니다: ' + e.message
            }
        };

        scwin.sendResultToParent(errorResult);
    }
};

// 부모 창으로 결과 전달 (WebSquare browserPopup 지원)
scwin.sendResultToParent = function(result) {
    try {
        console.log("부모 창으로 결과 전달:", result);

        // 1. WebSquare browserPopup 콜백 처리
        if (window.opener && window.opener.$c && window.opener.$c.util && window.opener.$c.util.getCallBackFunction) {
            console.log("WebSquare browserPopup 콜백 처리");

            // WebSquare의 콜백 함수 찾기
            const callbackFn = window.opener.$c.util.getCallBackFunction("github_oauth_popup");
            if (typeof callbackFn === 'function') {
                console.log("WebSquare 콜백 함수 호출");
                callbackFn(result);
            } else {
                console.log("WebSquare 콜백 함수를 찾을 수 없음, 직접 호출 시도");
                // 직접 콜백 함수 호출 시도
                if (window.opener.githubAuthCallback) {
                    window.opener.githubAuthCallback(result);
                }
            }

            // 팝업 닫기
            setTimeout(function() {
                window.close();
            }, 1000);
            return;
        }

        // 2. window.opener를 통한 일반 콜백
        if (window.opener && !window.opener.closed) {
            console.log("window.opener 직접 콜백 호출");

            // 콜백 함수가 있는지 확인
            if (typeof window.opener.githubAuthCallback === 'function') {
                window.opener.githubAuthCallback(result);
            } else {
                // postMessage로 전달
                window.opener.postMessage({
                    type: 'githubAuthResult',
                    result: result
                }, window.location.origin);
            }

            // 팝업 닫기
            setTimeout(function() {
                window.close();
            }, 1000);
            return;
        }

        // 3. 부모 프레임으로 전달 (iframe 방식)
        if (window.parent && window.parent !== window) {
            console.log("window.parent로 결과 전달");

            if (typeof window.parent.githubAuthCallback === 'function') {
                window.parent.githubAuthCallback(result);
            } else {
                window.parent.postMessage({
                    type: 'githubAuthResult',
                    result: result
                }, window.location.origin);
            }
            return;
        }

        console.warn("부모 창을 찾을 수 없습니다. 수동으로 팝업을 닫아주세요.");

    } catch (e) {
        console.error("부모 창으로 결과 전달 실패:", e);

        // 실패 시에도 팝업 닫기 시도
        setTimeout(function() {
            try {
                window.close();
            } catch (e) {
                console.log("창 닫기 실패:", e);
            }
        }, 2000);
    }
};
